// Stub JWT module for development when network is unavailable
// This is a temporary workaround - replace with real jsonwebtoken when npm install works

const JWT_SECRET = process.env.JWT_SECRET || "your_jwt_secret_key_change_this_in_production";

module.exports = {
  sign: (payload, secret, options) => {
    // Simplified JWT-like token generation
    const header = Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })).toString('base64');
    const body = Buffer.from(JSON.stringify({ ...payload, iat: Date.now(), exp: Date.now() + (7 * 24 * 60 * 60 * 1000) })).toString('base64');
    const signature = Buffer.from('stub_signature').toString('base64');
    return `${header}.${body}.${signature}`;
  },
  
  verify: (token, secret) => {
    try {
      if (!token || token.split('.').length !== 3) {
        throw new Error('Invalid token');
      }
      const parts = token.split('.');
      const payload = JSON.parse(Buffer.from(parts[1], 'base64').toString());
      if (payload.exp && payload.exp < Date.now()) {
        throw new Error('Token expired');
      }
      return payload;
    } catch (err) {
      throw new Error('Invalid token');
    }
  },

  decode: (token) => {
    try {
      const parts = token.split('.');
      return JSON.parse(Buffer.from(parts[1], 'base64').toString());
    } catch (err) {
      return null;
    }
  }
};
